import asyncio

async def collect(outcomes, attempts=2, timeout=0.2):
    for outcome in outcomes[:attempts]:
        delay = 0.6 if outcome == "timeout" else 0.001
        try:
            await asyncio.wait_for(asyncio.sleep(delay), timeout=timeout)
        except asyncio.TimeoutError:
            continue
        if outcome == "error":
            return "failed"
        return outcome
    return "timed out"

async def collect_pair():
    return await asyncio.gather(
        collect(["timeout", "ready"]),
        collect(["timeout"])
    )

print(asyncio.run(collect_pair()))

